"""A spreadsheet formula engine (Python 3.11, standard library only).

Exposes class Sheet with set/get_raw/get/undo/dependents/to_csv.
Cell references are Excel style: columns A..ZZ, rows 1..9999
(case-insensitive on input, canonical upper-case in output).
"""

import math
import re
import sys
from decimal import ROUND_HALF_UP, Decimal, InvalidOperation, localcontext

sys.setrecursionlimit(100000)

__all__ = ["Sheet"]


# ---------------------------------------------------------------------------
# Error codes (exact strings returned by get() and written into CSV fields).
# ---------------------------------------------------------------------------

DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
NAME = "#NAME?"
PARSE = "#PARSE!"
CYCLE = "#CYCLE!"


class _Err:
    """Internal error value (distinct class so error codes are never
    confused with ordinary text values)."""

    __slots__ = ("code",)

    def __init__(self, code):
        self.code = code

    def __repr__(self):
        return "_Err(%r)" % (self.code,)


ERR_DIV0 = _Err(DIV0)
ERR_VALUE = _Err(VALUE)
ERR_REF = _Err(REF)
ERR_NAME = _Err(NAME)
ERR_PARSE = _Err(PARSE)
ERR_CYCLE = _Err(CYCLE)


class _Empty:
    """Marker for an empty cell: coerces to 0.0 arithmetically, "" as text."""

    __slots__ = ()

    def __repr__(self):
        return "<empty>"


EMPTY = _Empty()
_MISS = object()


class _RangeVal:
    """Marker for a range expression; corners normalized (r1<=r2, c1<=c2)."""

    __slots__ = ("r1", "c1", "r2", "c2")

    def __init__(self, r1, c1, r2, c2):
        if r1 <= r2:
            self.r1, self.r2 = r1, r2
        else:
            self.r1, self.r2 = r2, r1
        if c1 <= c2:
            self.c1, self.c2 = c1, c2
        else:
            self.c1, self.c2 = c2, c1


# ---------------------------------------------------------------------------
# Cell references.
# ---------------------------------------------------------------------------

_API_REF_RE = re.compile(r"[A-Za-z]{1,2}[0-9]{1,4}\Z")
_SHAPE_RE = re.compile(r"[A-Za-z]+[0-9]+\Z")
_NUM_RE = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?\Z")


def _col_index(letters):
    """1-based column index for a 1-2 letter column name (A..ZZ)."""
    if len(letters) == 1:
        return ord(letters) - 64
    return 27 + (ord(letters[0]) - 65) * 26 + (ord(letters[1]) - 65)


def _col_name(col):
    """Canonical column letters for a 1-based index (1..702)."""
    if col <= 26:
        return chr(64 + col)
    col -= 27
    return chr(65 + col // 26) + chr(65 + col % 26)


def _ref_coords(letters, digits):
    """(row, col) for a reference token, or None when out of bounds."""
    if len(letters) > 2:
        return None
    row = int(digits)
    if row < 1 or row > 9999:
        return None
    return (row, _col_index(letters))


def _parse_api_ref(ref):
    """Validate a user-supplied reference; return canonical (row, col)."""
    if not isinstance(ref, str) or not _API_REF_RE.fullmatch(ref):
        raise ValueError("invalid cell reference: %r" % (ref,))
    up = ref.upper()
    j = 0
    while up[j].isalpha():
        j += 1
    row = int(up[j:])
    if row < 1 or row > 9999:
        raise ValueError("invalid cell reference: %r" % (ref,))
    return (row, _col_index(up[:j]))


# ---------------------------------------------------------------------------
# Value coercions and operator application.
# ---------------------------------------------------------------------------

def _to_num(v):
    """Arithmetic coercion: float, or ERR_VALUE for text/range."""
    if v is EMPTY:
        return 0.0
    if isinstance(v, bool):
        return 1.0 if v else 0.0
    if isinstance(v, float):
        return v
    return ERR_VALUE


def _to_text(v):
    """Text coercion (also used for CSV fields)."""
    if isinstance(v, str):
        return v
    if isinstance(v, _Err):
        return v.code
    if v is EMPTY:
        return ""
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if v.is_integer() and -1e15 < v < 1e15:
        return str(int(v))
    return repr(v)


def _apply_bin(op, left, right):
    if op == "&":
        if isinstance(left, _RangeVal) or isinstance(right, _RangeVal):
            return ERR_VALUE
        return _to_text(left) + _to_text(right)
    a = _to_num(left)
    if isinstance(a, _Err):
        return a
    b = _to_num(right)
    if isinstance(b, _Err):
        return b
    if op == "+":
        res = a + b
    elif op == "-":
        res = a - b
    elif op == "*":
        res = a * b
    elif op == "/":
        if b == 0.0:
            return ERR_DIV0
        res = a / b
    else:  # "^"
        if a == 0.0 and b < 0.0:
            return ERR_DIV0
        try:
            res = math.pow(a, b)
        except (ValueError, OverflowError):
            return ERR_VALUE
    if not math.isfinite(res):
        return ERR_VALUE
    return res


def _apply_cmp(op, left, right):
    if isinstance(left, _RangeVal) or isinstance(right, _RangeVal):
        return ERR_VALUE
    if isinstance(left, str):
        if isinstance(right, str):
            a, b = left.lower(), right.lower()
        elif right is EMPTY:
            a, b = left.lower(), ""
        else:
            return ERR_VALUE
    elif isinstance(right, str):
        if left is EMPTY:
            a, b = "", right.lower()
        else:
            return ERR_VALUE
    else:
        a = _to_num(left)
        b = _to_num(right)
    if op == "=":
        return a == b
    if op == "<>":
        return a != b
    if op == "<":
        return a < b
    if op == ">":
        return a > b
    if op == "<=":
        return a <= b
    return a >= b


def _round_number(x, digits):
    """Round half away from zero to `digits` decimals (exact on ties)."""
    if not math.isfinite(x) or not math.isfinite(digits):
        return ERR_VALUE
    d = int(digits)  # truncate toward zero
    if d > 400:
        d = 400
    elif d < -400:
        d = -400
    try:
        with localcontext() as ctx:
            ctx.prec = 1500
            q = Decimal(1).scaleb(-d)
            fv = float(Decimal(repr(x)).quantize(q, rounding=ROUND_HALF_UP))
    except (InvalidOperation, ValueError, OverflowError, ZeroDivisionError):
        return ERR_VALUE
    if not math.isfinite(fv):
        return ERR_VALUE
    return fv


def _literal_value(raw):
    """Value of a non-formula cell: float when the whole text is a number."""
    s = raw.strip()
    if _NUM_RE.match(s):
        try:
            return float(s)
        except ValueError:
            pass
    return raw


# ---------------------------------------------------------------------------
# Formula tokenizer / parser.
# ---------------------------------------------------------------------------

class _ParseError(Exception):
    pass


_CMP_SET = frozenset(("=", "<>", "<", ">", "<=", ">="))

_TOKEN_RE = re.compile(
    r"\s*(?:(?P<num>(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?)"
    r'|(?P<str>"(?:[^"]|"")*")'
    r"|(?P<id>[A-Za-z_][A-Za-z0-9_]*)"
    r"|(?P<op><>|<=|>=|[=<>+\-*/^&(),:]))"
)


def _tokenize(src):
    """Token list of (kind, value) pairs, or None on a syntax error."""
    toks = []
    pos = 0
    n = len(src)
    while pos < n:
        m = _TOKEN_RE.match(src, pos)
        if m is None:
            if src[pos:].strip() == "":
                break
            return None
        kind = m.lastgroup
        text = m.group(kind)
        if kind == "num":
            toks.append(("num", float(text)))
        elif kind == "str":
            toks.append(("str", text[1:-1].replace('""', '"')))
        elif kind == "id":
            toks.append(("id", text))
        else:
            toks.append(("op", text))
        pos = m.end()
    return toks


class _Parser:
    """Recursive-descent parser. AST nodes (tuples):
    ('num', f) ('str', s) ('bool', b) ('ref', LET, DIG)
    ('range', L1, D1, L2, D2) ('name', text) ('perr', code)
    ('un', op, node) ('bin', op, l, r) ('cmp', op, l, r) ('call', NAME, args)
    """

    __slots__ = ("toks", "i")

    def __init__(self, toks):
        self.toks = toks
        self.i = 0

    def parse(self):
        node = self._cmp()
        if self.i != len(self.toks):
            raise _ParseError()
        return node

    def _peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def _cmp(self):
        node = self._concat()
        while True:
            t = self._peek()
            if t is not None and t[0] == "op" and t[1] in _CMP_SET:
                self.i += 1
                node = ("cmp", t[1], node, self._concat())
            else:
                return node

    def _concat(self):
        node = self._add()
        while True:
            t = self._peek()
            if t is not None and t[0] == "op" and t[1] == "&":
                self.i += 1
                node = ("bin", "&", node, self._add())
            else:
                return node

    def _add(self):
        node = self._mul()
        while True:
            t = self._peek()
            if t is not None and t[0] == "op" and (t[1] == "+" or t[1] == "-"):
                self.i += 1
                node = ("bin", t[1], node, self._mul())
            else:
                return node

    def _mul(self):
        node = self._unary()
        while True:
            t = self._peek()
            if t is not None and t[0] == "op" and (t[1] == "*" or t[1] == "/"):
                self.i += 1
                node = ("bin", t[1], node, self._unary())
            else:
                return node

    def _unary(self):
        t = self._peek()
        if t is not None and t[0] == "op" and (t[1] == "+" or t[1] == "-"):
            self.i += 1
            return ("un", t[1], self._unary())
        return self._power()

    def _power(self):
        node = self._primary()
        t = self._peek()
        if t is not None and t[0] == "op" and t[1] == "^":
            self.i += 1
            return ("bin", "^", node, self._unary())
        return node

    def _primary(self):
        t = self._peek()
        if t is None:
            raise _ParseError()
        kind, val = t
        if kind == "num":
            self.i += 1
            return ("num", val)
        if kind == "str":
            self.i += 1
            return ("str", val)
        if kind == "op":
            if val == "(":
                self.i += 1
                node = self._cmp()
                t2 = self._peek()
                if t2 is None or t2[0] != "op" or t2[1] != ")":
                    raise _ParseError()
                self.i += 1
                return node
            raise _ParseError()
        # identifier: function call, TRUE/FALSE, reference/range, or bare name
        self.i += 1
        nxt = self._peek()
        if nxt is not None and nxt[0] == "op" and nxt[1] == "(":
            self.i += 1
            args = []
            t2 = self._peek()
            if t2 is not None and t2[0] == "op" and t2[1] == ")":
                self.i += 1
                return ("call", val.upper(), args)
            while True:
                args.append(self._cmp())
                t2 = self._peek()
                if t2 is None or t2[0] != "op":
                    raise _ParseError()
                if t2[1] == ",":
                    self.i += 1
                    continue
                if t2[1] == ")":
                    self.i += 1
                    return ("call", val.upper(), args)
                raise _ParseError()
        upper = val.upper()
        if upper == "TRUE":
            return ("bool", True)
        if upper == "FALSE":
            return ("bool", False)
        if _SHAPE_RE.fullmatch(val):
            j = 0
            while val[j].isalpha():
                j += 1
            letters = val[:j].upper()
            digits = val[j:]
            nxt = self._peek()
            if nxt is not None and nxt[0] == "op" and nxt[1] == ":":
                self.i += 1
                t2 = self._peek()
                if t2 is None or t2[0] != "id" or not _SHAPE_RE.fullmatch(t2[1]):
                    raise _ParseError()
                self.i += 1
                other = t2[1]
                k = 0
                while other[k].isalpha():
                    k += 1
                return ("range", letters, digits, other[:k].upper(), other[k:])
            return ("ref", letters, digits)
        return ("name", val)


def _parse_formula(src):
    """Parse a formula body (text after '='). Failures become ('perr', PARSE)
    so they evaluate to #PARSE!."""
    toks = _tokenize(src)
    if toks is None:
        return ("perr", PARSE)
    try:
        return _Parser(toks).parse()
    except _ParseError:
        return ("perr", PARSE)
    except RecursionError:
        return ("perr", PARSE)


def _collect_ref_nodes(node, out):
    """Static walk collecting ('ref', ...) / ('range', ...) nodes (includes
    both IF branches)."""
    t = node[0]
    if t == "ref" or t == "range":
        out.append(node)
    elif t == "un":
        _collect_ref_nodes(node[2], out)
    elif t == "bin" or t == "cmp":
        _collect_ref_nodes(node[2], out)
        _collect_ref_nodes(node[3], out)
    elif t == "call":
        for a in node[2]:
            _collect_ref_nodes(a, out)


# ---------------------------------------------------------------------------
# The spreadsheet.
# ---------------------------------------------------------------------------

class Sheet:
    """A spreadsheet supporting formulas, undo, dependency queries and CSV
    export. Values are float / str / bool / None (empty) / error-code str."""

    _INDEX_CAP = 1024  # ranges up to this many cells get per-cell reverse indexes

    def __init__(self):
        self.cells = {}         # (row, col) -> raw text (non-empty cells only)
        self._values = {}       # (row, col) -> float | str | bool | _Err
        self._asts = {}         # (row, col) -> parsed formula AST
        self._dep_spec = {}     # (row, col) -> (singles set, [(rect, indexed)])
        self._rev = {}          # (row, col) -> set of formula cells reading it
        self._big_ranges = []   # [(cell, rect)] ranges too large to index
        self._formulas = set()  # (row, col) of cells whose raw starts with '='
        self._undo_log = []     # [(cell, previous raw or None)]
        self._busy = set()      # cells currently being evaluated (guard)

    # ----------------------------------------------------------- public API

    def set(self, ref, raw):
        """Store raw text exactly as given; raw == "" clears the cell."""
        if not isinstance(raw, str):
            raise TypeError("cell content must be a string")
        rc = _parse_api_ref(ref)
        self._undo_log.append((rc, self.cells.get(rc)))
        self._uninstall(rc)
        if raw == "":
            self.cells.pop(rc, None)
        else:
            self.cells[rc] = raw
        self._invalidate_from(rc)
        if raw != "":
            self._install_deps(rc)

    def get_raw(self, ref):
        """Stored raw text, or None for an empty cell."""
        return self.cells.get(_parse_api_ref(ref))

    def get(self, ref):
        """Evaluated value: float, str, bool, None, or an error-code string."""
        return self._get_rc(_parse_api_ref(ref))

    def undo(self):
        """Revert the most recent set() call; False when nothing to undo."""
        if not self._undo_log:
            return False
        rc, prev = self._undo_log.pop()
        self._uninstall(rc)
        if prev is None:
            self.cells.pop(rc, None)
        else:
            self.cells[rc] = prev
        self._invalidate_from(rc)
        if prev is not None:
            self._install_deps(rc)
        return True

    def dependents(self, ref):
        """Formula cells depending on ref directly or transitively (through
        references or ranges), canonical refs sorted by (row, column)."""
        rc = _parse_api_ref(ref)
        result = set()
        seen = {rc}
        stack = [rc]
        big = self._big_ranges
        while stack:
            cur = stack.pop()
            readers = self._rev.get(cur)
            if readers:
                for h in readers:
                    if h not in seen:
                        seen.add(h)
                        result.add(h)
                        stack.append(h)
            for h, rect in big:
                if h not in seen and rect[0] <= cur[0] <= rect[2] \
                        and rect[1] <= cur[1] <= rect[3]:
                    seen.add(h)
                    result.add(h)
                    stack.append(h)
        result.discard(rc)
        return [_col_name(c) + str(r) for r, c in sorted(result)]

    def to_csv(self):
        """CSV of the rectangle from A1 to the last non-empty row/column."""
        if not self.cells:
            return ""
        max_row = 0
        max_col = 0
        for r, c in self.cells:
            if r > max_row:
                max_row = r
            if c > max_col:
                max_col = c
        get = self._get_rc
        lines = []
        for r in range(1, max_row + 1):
            fields = []
            for c in range(1, max_col + 1):
                v = get((r, c))
                s = "" if v is None else _to_text(v)
                if "," in s or '"' in s or "\n" in s:
                    s = '"' + s.replace('"', '""') + '"'
                fields.append(s)
            lines.append(",".join(fields))
        return "\n".join(lines)

    # ----------------------------------------------------------- internals

    def _get_rc(self, rc):
        raw = self.cells.get(rc)
        if raw is None:
            return None
        v = self._values.get(rc, _MISS)
        if v is _MISS:
            if raw[0] == "=":
                self._evaluate_component(rc)
                v = self._values.get(rc, ERR_VALUE)
            else:
                v = _literal_value(raw)
        if isinstance(v, _Err):
            return v.code
        return v

    def _uninstall(self, rc):
        """Remove a cell's dependency-index contributions and cached state."""
        self._formulas.discard(rc)
        spec = self._dep_spec.pop(rc, None)
        if spec is not None:
            singles, ranges = spec
            rev = self._rev
            for d in singles:
                s = rev.get(d)
                if s is not None:
                    s.discard(rc)
                    if not s:
                        del rev[d]
            for rect, indexed in ranges:
                if indexed:
                    for r in range(rect[0], rect[2] + 1):
                        for c in range(rect[1], rect[3] + 1):
                            s = rev.get((r, c))
                            if s is not None:
                                s.discard(rc)
                                if not s:
                                    del rev[(r, c)]
                else:
                    self._big_ranges = [
                        e for e in self._big_ranges
                        if not (e[0] == rc and e[1] == rect)
                    ]
        self._asts.pop(rc, None)
        self._values.pop(rc, None)

    def _install_deps(self, rc):
        """Parse (if formula), cache literal values, and index dependencies."""
        raw = self.cells.get(rc)
        if raw is None:
            return
        if raw[0] != "=":
            self._values[rc] = _literal_value(raw)
            return
        ast = _parse_formula(raw[1:])
        self._asts[rc] = ast
        self._formulas.add(rc)
        nodes = []
        _collect_ref_nodes(ast, nodes)
        rev = self._rev
        singles = set()
        ranges = []
        cap = self._INDEX_CAP
        for nd in nodes:
            if nd[0] == "ref":
                coords = _ref_coords(nd[1], nd[2])
                if coords is not None:
                    rev.setdefault(coords, set()).add(rc)
                    singles.add(coords)
            else:
                c1 = _ref_coords(nd[1], nd[2])
                c2 = _ref_coords(nd[3], nd[4])
                if c1 is None or c2 is None:
                    continue
                if c1[0] <= c2[0]:
                    r1, r2 = c1[0], c2[0]
                else:
                    r1, r2 = c2[0], c1[0]
                if c1[1] <= c2[1]:
                    k1, k2 = c1[1], c2[1]
                else:
                    k1, k2 = c2[1], c1[1]
                rect = (r1, k1, r2, k2)
                if (r2 - r1 + 1) * (k2 - k1 + 1) <= cap:
                    for r in range(r1, r2 + 1):
                        for c in range(k1, k2 + 1):
                            rev.setdefault((r, c), set()).add(rc)
                    ranges.append((rect, True))
                else:
                    self._big_ranges.append((rc, rect))
                    ranges.append((rect, False))
        self._dep_spec[rc] = (singles, ranges)

    def _invalidate_from(self, rc):
        """Drop cached values of rc and every transitive dependent of rc."""
        values = self._values
        rev = self._rev
        big = self._big_ranges
        seen = {rc}
        stack = [rc]
        while stack:
            cur = stack.pop()
            values.pop(cur, None)
            readers = rev.get(cur)
            if readers:
                for h in readers:
                    if h not in seen:
                        seen.add(h)
                        stack.append(h)
            for h, rect in big:
                if h not in seen and rect[0] <= cur[0] <= rect[2] \
                        and rect[1] <= cur[1] <= rect[3]:
                    seen.add(h)
                    stack.append(h)

    def _dep_formula_cells(self, f):
        """Formula cells that f directly depends on (current graph state)."""
        ast = self._asts.get(f)
        if ast is None:
            return []
        nodes = []
        _collect_ref_nodes(ast, nodes)
        if not nodes:
            return []
        formulas = self._formulas
        deps = []
        seen = set()
        for nd in nodes:
            if nd[0] == "ref":
                coords = _ref_coords(nd[1], nd[2])
                if coords is not None and coords in formulas and coords not in seen:
                    seen.add(coords)
                    deps.append(coords)
            else:
                c1 = _ref_coords(nd[1], nd[2])
                c2 = _ref_coords(nd[3], nd[4])
                if c1 is None or c2 is None:
                    continue
                if c1[0] <= c2[0]:
                    r1, r2 = c1[0], c2[0]
                else:
                    r1, r2 = c2[0], c1[0]
                if c1[1] <= c2[1]:
                    k1, k2 = c1[1], c2[1]
                else:
                    k1, k2 = c2[1], c1[1]
                area = (r2 - r1 + 1) * (k2 - k1 + 1)
                if area <= 256 or area <= len(formulas):
                    for r in range(r1, r2 + 1):
                        for c in range(k1, k2 + 1):
                            cell = (r, c)
                            if cell in formulas and cell not in seen:
                                seen.add(cell)
                                deps.append(cell)
                else:
                    for cell in formulas:
                        if r1 <= cell[0] <= r2 and k1 <= cell[1] <= k2 \
                                and cell not in seen:
                            seen.add(cell)
                            deps.append(cell)
        return deps

    def _collect(self, start):
        """Dependency subgraph of dirty formula cells reachable from start.
        Cells with an up-to-date cached value are treated as leaves."""
        adj = {}
        values = self._values
        stack = [start]
        while stack:
            f = stack.pop()
            if f in adj:
                continue
            edge = [g for g in self._dep_formula_cells(f) if g not in values]
            adj[f] = edge
            for g in edge:
                if g not in adj:
                    stack.append(g)
        return adj

    def _tarjan(self, adj):
        """Iterative Tarjan SCC; components come out dependencies-first."""
        idx = {}
        low = {}
        on = set()
        st = []
        sccs = []
        counter = 0
        for root in adj:
            if root in idx:
                continue
            idx[root] = low[root] = counter
            counter += 1
            st.append(root)
            on.add(root)
            work = [(root, iter(adj[root]))]
            while work:
                v, it = work[-1]
                pushed = False
                for w in it:
                    iw = idx.get(w)
                    if iw is None:
                        idx[w] = low[w] = counter
                        counter += 1
                        st.append(w)
                        on.add(w)
                        work.append((w, iter(adj[w])))
                        pushed = True
                        break
                    if iw < low[v]:
                        low[v] = iw
                if pushed:
                    continue
                work.pop()
                lv = low[v]
                if lv == idx[v]:
                    scc = []
                    while True:
                        w = st.pop()
                        on.discard(w)
                        scc.append(w)
                        if w == v:
                            break
                    sccs.append(scc)
                if work:
                    pv = work[-1][0]
                    if lv < low[pv]:
                        low[pv] = lv
        return sccs

    def _evaluate_component(self, start):
        """Evaluate start and every dirty formula cell it (transitively)
        needs, iteratively (no recursion over cells). Cells in a cycle get
        #CYCLE!; everything else evaluates in dependency order."""
        adj = self._collect(start)
        values = self._values
        busy = self._busy
        for scc in self._tarjan(adj):
            if len(scc) > 1 or scc[0] in adj[scc[0]]:
                cyc = ERR_CYCLE
                for f in scc:
                    values[f] = cyc
                continue
            f = scc[0]
            ast = self._asts.get(f)
            if ast is None:
                raw = self.cells.get(f)
                if raw is not None and raw[0] == "=":
                    ast = _parse_formula(raw[1:])
                    self._asts[f] = ast
                else:
                    ast = ("perr", PARSE)
            busy.add(f)
            try:
                v = self._eval(ast)
            except RecursionError:
                v = ERR_PARSE
            finally:
                busy.discard(f)
            if v is EMPTY:
                v = 0.0
            elif isinstance(v, _RangeVal):
                v = ERR_VALUE
            elif isinstance(v, float) and not math.isfinite(v):
                v = ERR_VALUE
            values[f] = v

    def _cell_value(self, rc):
        """Current value of a cell: cached value, literal, or EMPTY marker."""
        v = self._values.get(rc, _MISS)
        if v is not _MISS:
            return v
        if rc in self._formulas:
            if rc not in self._busy:
                self._evaluate_component(rc)
                return self._values.get(rc, ERR_CYCLE)
            return ERR_CYCLE
        return EMPTY

    def _range_values(self, rv):
        """Yield cell values of a range row by row, left to right."""
        cell_value = self._cell_value
        for r in range(rv.r1, rv.r2 + 1):
            for c in range(rv.c1, rv.c2 + 1):
                yield cell_value((r, c))

    def _eval(self, node):
        t = node[0]
        if t == "num" or t == "str" or t == "bool":
            return node[1]
        if t == "ref":
            coords = _ref_coords(node[1], node[2])
            if coords is None:
                return ERR_REF
            return self._cell_value(coords)
        if t == "range":
            c1 = _ref_coords(node[1], node[2])
            c2 = _ref_coords(node[3], node[4])
            if c1 is None or c2 is None:
                return ERR_REF
            return _RangeVal(c1[0], c1[1], c2[0], c2[1])
        if t == "perr":
            return _Err(node[1])
        if t == "name":
            return ERR_NAME
        if t == "un":
            v = self._eval(node[2])
            if isinstance(v, _Err):
                return v
            n = _to_num(v)
            if isinstance(n, _Err):
                return n
            r = -n if node[1] == "-" else n
            return r if math.isfinite(r) else ERR_VALUE
        if t == "bin":
            l = self._eval(node[2])
            if isinstance(l, _Err):
                return l
            r = self._eval(node[3])
            if isinstance(r, _Err):
                return r
            return _apply_bin(node[1], l, r)
        if t == "cmp":
            l = self._eval(node[2])
            if isinstance(l, _Err):
                return l
            r = self._eval(node[3])
            if isinstance(r, _Err):
                return r
            return _apply_cmp(node[1], l, r)
        if t == "call":
            return self._call(node[1], node[2])
        return ERR_VALUE

    def _call(self, name, arg_asts):
        if name == "IF":
            return self._fn_if(arg_asts)
        fn = _FUNCS.get(name)
        if fn is None:
            return ERR_NAME
        vals = []
        for a in arg_asts:
            v = self._eval(a)
            if isinstance(v, _Err) and name != "COUNT":
                return v
            vals.append(v)
        return fn(self, vals, arg_asts)

    def _fn_if(self, arg_asts):
        if not arg_asts:
            return ERR_VALUE
        cond = self._eval(arg_asts[0])
        if isinstance(cond, _Err):
            return cond
        if isinstance(cond, str) or isinstance(cond, _RangeVal):
            return ERR_VALUE
        n = len(arg_asts)
        if n < 2 or n > 3:
            return ERR_VALUE
        if cond is not EMPTY and cond != 0:
            return self._eval(arg_asts[1])
        if n == 3:
            return self._eval(arg_asts[2])
        return False

    def _aggregate(self, name, vals, asts):
        count_mode = name == "COUNT"
        nums = []
        append = nums.append
        for i, v in enumerate(vals):
            if isinstance(v, _RangeVal):
                for cv in self._range_values(v):
                    if isinstance(cv, float):
                        append(cv)
                    elif isinstance(cv, _Err):
                        if not count_mode:
                            return cv
            elif asts[i][0] == "ref":
                # single-cell reference: cell semantics (empty/text/bool skip)
                if isinstance(v, float):
                    append(v)
                elif isinstance(v, _Err):
                    if not count_mode:
                        return v
            else:
                # directly given expression
                if isinstance(v, bool):
                    append(1.0 if v else 0.0)
                elif isinstance(v, float):
                    append(v)
                elif v is EMPTY:
                    append(0.0)
                elif isinstance(v, _Err):
                    continue
                elif not count_mode:
                    return ERR_VALUE
        if count_mode:
            return float(len(nums))
        if name == "SUM":
            s = 0.0
            for x in nums:
                s += x
            return s if math.isfinite(s) else ERR_VALUE
        if name == "AVERAGE":
            if not nums:
                return ERR_DIV0
            s = 0.0
            for x in nums:
                s += x
            if not math.isfinite(s):
                return ERR_VALUE
            r = s / len(nums)
            return r if math.isfinite(r) else ERR_VALUE
        if name == "MIN":
            if not nums:
                return 0.0
            m = min(nums)
            return m if math.isfinite(m) else ERR_VALUE
        if name == "MAX":
            if not nums:
                return 0.0
            m = max(nums)
            return m if math.isfinite(m) else ERR_VALUE
        return ERR_VALUE

    def _fn_sum(self, vals, asts):
        return self._aggregate("SUM", vals, asts)

    def _fn_average(self, vals, asts):
        return self._aggregate("AVERAGE", vals, asts)

    def _fn_min(self, vals, asts):
        return self._aggregate("MIN", vals, asts)

    def _fn_max(self, vals, asts):
        return self._aggregate("MAX", vals, asts)

    def _fn_count(self, vals, asts):
        return self._aggregate("COUNT", vals, asts)

    def _fn_concat(self, vals, asts):
        parts = []
        for v in vals:
            if isinstance(v, _RangeVal):
                for cv in self._range_values(v):
                    if isinstance(cv, _Err):
                        return cv
                    parts.append(_to_text(cv))
            elif isinstance(v, _Err):
                return v
            else:
                parts.append(_to_text(v))
        return "".join(parts)

    def _fn_len(self, vals, asts):
        if len(vals) != 1:
            return ERR_VALUE
        v = vals[0]
        if isinstance(v, _RangeVal):
            return ERR_VALUE
        return float(len(_to_text(v)))

    def _fn_abs(self, vals, asts):
        if len(vals) != 1:
            return ERR_VALUE
        n = _to_num(vals[0])
        if isinstance(n, _Err):
            return n
        r = abs(n)
        return r if math.isfinite(r) else ERR_VALUE

    def _fn_round(self, vals, asts):
        if len(vals) != 1 and len(vals) != 2:
            return ERR_VALUE
        x = _to_num(vals[0])
        if isinstance(x, _Err):
            return x
        if len(vals) == 2:
            d = _to_num(vals[1])
            if isinstance(d, _Err):
                return d
        else:
            d = 0.0
        return _round_number(x, d)


